const guidStr = $input.item.json.manager_guid || "";
const tgUserId = $input.item.json.tg_user_id;


const hexStr = guidStr.replace(/-/g, "").toLowerCase();

if (hexStr.length !== 32) {
    return { error: "Invalid GUID length" };
}


const A = hexStr.substring(0, 8);
const B = hexStr.substring(8, 12);
const C = hexStr.substring(12, 16);
const D = hexStr.substring(16, 20);
const E = hexStr.substring(20, 32);


const resultHex = D + E + C + B + A;

return {
    manager_guid_bin: resultHex,
    manager_guid_formatted: `${D}-${E}-${C}-${B}-${A}`,
    tg_user_id: tgUserId
};

