return [{ json: {
  chat_id: $('Universal Router').first().json.chat_id,
  text: `✅ Вітаємо, <b>${dealerName}</b>!\n\nПрофіль дилера прив’язано. У меню доступні лише замовлення вашого контрагента.`,
  reply_markup: { keyboard, resize_keyboard: true, one_time_keyboard: false, is_persistent: true }
}}];

const o=$json.order??{};
const money=value=>new Intl.NumberFormat('uk-UA',{maximumFractionDigits:2}).format(Number(value||0));
const date=value=>value?new Intl.DateTimeFormat('uk-UA').format(new Date(value)):'—';
const line=(label,value)=>`${label}: <b>${value||'—'}</b>`;
return [{json:{chat_id:$('Parse portal command').first().json.chat_id,text:`<b>Замовлення №${o.number??'—'}</b>

${line('Статус',o.status)}
${line('Дата замовлення',date(o.date))}
${line('Прорахунок',o.calculation_number)}
${line('Конструкції',o.count)}

<b>Оплата</b>
Сума: <b>${money(o.amount)} ${o.currency??'грн'}</b>
Оплачено: <b>${money(o.paid)} ${o.currency??'грн'}</b>
Борг: <b>${money(o.debt)} ${o.currency??'грн'}</b>

<b>Виконання</b>
${line('План виробництва',date(o.planned_production_from))}
${line('Готовність',date(o.actual_ready_from))}
${line('План доставки',date(o.planned_delivery))}
${line('Адреса доставки',o.delivery_address)}
${line('Отримувач',o.recipient)}`,reply_markup:{keyboard:[['📦 Замовлення'],['⬅️ Назад']],resize_keyboard:true,is_persistent:false}}}];

const rows=Array.isArray($json.reclamations)?$json.reclamations:[];
const fmtDate=value=>value?new Intl.DateTimeFormat('uk-UA').format(new Date(value)):'—';
const text=rows.slice(0,15).map((item,index)=>`${index+1}. <b>${item.number||'Без номера'}</b>
${item.status||'—'} • ${fmtDate(item.date)}${item.order_number?`
Замовлення: №${item.order_number}`:''}${item.description?`
${item.description.slice(0,180)}`:''}`).join('

');
return [{json:{chat_id:$('Parse portal command').first().json.chat_id,text:`<b>🛠 Рекламації (${rows.length})</b>

${text||'За цим статусом рекламацій не знайдено.'}`,reply_markup:{keyboard:[['🛠 Рекламації','📦 Замовлення'],['⬅️ Назад']],resize_keyboard:true,is_persistent:false}}}];

const rows=Array.isArray($json.additional_orders)?$json.additional_orders:[];
const money=value=>new Intl.NumberFormat('uk-UA',{maximumFractionDigits:2}).format(Number(value||0));
const fmtDate=value=>value?new Intl.DateTimeFormat('uk-UA').format(new Date(value)):'—';
const text=rows.slice(0,15).map((item,index)=>`${index+1}. <b>№${item.number||'—'}</b>
${item.status||'—'} • ${fmtDate(item.date)}
Сума: <b>${money(item.amount)} ${item.currency||'грн'}</b>${item.order_number?`
Основне замовлення: №${item.order_number}`:''}`).join('

');
return [{json:{chat_id:$('Parse portal command').first().json.chat_id,text:`<b>➕ Дозамовлення (${rows.length})</b>

${text||'Дозамовлень не знайдено.'}`,reply_markup:{keyboard:[['➕ Дозамовлення','📦 Замовлення'],['⬅️ Назад']],resize_keyboard:true,is_persistent:false}}}];

const counts=$json.status_counts??{};
const buttons=Object.entries(counts).sort((a,b)=>a[0].localeCompare(b[0],'uk')).map(([status,count])=>[{text:`${status} (${count})`,callback_data:`reclamation_status|${encodeURIComponent(status)}`}]);
const keyboard=[];for(let i=0;i<buttons.length;i+=2)keyboard.push(buttons.slice(i,i+2));
return [{json:{chat_id:$('Parse portal command').first().json.chat_id,text:`<b>🛠 Рекламації (${Object.values(counts).reduce((sum,value)=>sum+Number(value||0),0)})</b>\n\nОберіть статус:`,reply_markup:{inline_keyboard:keyboard.length?keyboard:[[{text:'Рекламацій немає',callback_data:'noop'}]]}}}];

return [{json:{chat_id:$('Parse portal command').first().json.chat_id,text:'<b>Пошук замовлення</b>

Надішліть номер замовлення, наприклад: <code>01-350435</code>.
Або використайте команду: <code>/order 01-350435</code>.',reply_markup:{keyboard:[['📦 Замовлення'],['⬅️ Назад']],resize_keyboard:true,is_persistent:false}}}];
